package dist

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"slices"
	"strings"
	"time"

	"github.com/Zxilly/cjv/internal/fsops"
)

// A group is one digest-keyed entry plus its interrupted publication files.
// Legacy temporary files have no digest key and form individual groups.
type cacheGroup struct {
	key       string
	temporary []string
}

type cacheItem struct {
	entry CacheEntry
	files []string
}

func validCacheKey(key string) bool {
	if key != strings.ToLower(key) {
		return false
	}
	decoded, err := hex.DecodeString(key)
	return err == nil && len(decoded) == sha256.Size
}

func temporarySuffix(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

// cacheFileOwner accepts only names generated by cjv. A filename, never a path
// from JSON, determines both its lock and the files cleanup may remove.
func cacheFileOwner(name string) (key string, temporary, owned bool) {
	for _, suffix := range []string{".data", ".json"} {
		if key, ok := strings.CutSuffix(name, suffix); ok && validCacheKey(key) {
			return key, false, true
		}
		prefix, tail, ok := strings.Cut(strings.TrimPrefix(name, "."), suffix+".partial-")
		if strings.HasPrefix(name, ".") && ok && validCacheKey(prefix) && temporarySuffix(tail) {
			return prefix, true, true
		}
	}
	// Previous versions used these unkeyed CreateTemp patterns. New writers
	// always use keyed names, so no live new writer can own a legacy temporary.
	for _, prefix := range []string{".artifact-", ".cjv-tmp-"} {
		if suffix, ok := strings.CutPrefix(name, prefix); ok && temporarySuffix(suffix) {
			return "", true, true
		}
	}
	return "", false, false
}

func scanCacheGroups(root *os.Root) ([]cacheGroup, error) {
	directory, err := root.Open(".")
	if err != nil {
		return nil, err
	}
	defer directory.Close() //nolint:errcheck // read-only
	entries, err := directory.ReadDir(-1)
	if err != nil {
		return nil, err
	}
	groups := make(map[string]*cacheGroup)
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		key, temporary, owned := cacheFileOwner(entry.Name())
		if !owned {
			continue
		}
		groupID := key
		if groupID == "" {
			groupID = entry.Name()
		}
		group := groups[groupID]
		if group == nil {
			group = &cacheGroup{key: key}
			groups[groupID] = group
		}
		if temporary {
			group.temporary = append(group.temporary, entry.Name())
		}
	}
	keys := make([]string, 0, len(groups))
	for key := range groups {
		keys = append(keys, key)
	}
	slices.Sort(keys)
	result := make([]cacheGroup, 0, len(groups))
	for _, key := range keys {
		group := groups[key]
		slices.Sort(group.temporary)
		result = append(result, *group)
	}
	return result, nil
}

func inspectCacheGroup(root *os.Root, group cacheGroup) []cacheItem {
	var result []cacheItem
	if group.key != "" {
		item := inspectCacheRecord(root, group.key)
		if len(item.files) > 0 {
			result = append(result, item)
		}
	}
	for _, name := range group.temporary {
		info, err := root.Lstat(name)
		if err != nil || info.IsDir() {
			continue
		}
		result = append(result, cacheItem{
			entry: CacheEntry{Key: name, Kind: "temporary", Size: info.Size(), Updated: info.ModTime(), Problem: "incomplete cache publication"},
			files: []string{name},
		})
	}
	return result
}

func inspectCacheRecord(root *os.Root, key string) cacheItem {
	item := cacheItem{entry: CacheEntry{Key: key, Kind: "orphan", Problem: "cache metadata is missing"}}
	var dataInfo, recordInfo os.FileInfo
	for _, suffix := range []string{".data", ".json"} {
		name := key + suffix
		info, err := root.Lstat(name)
		if err != nil || info.IsDir() {
			continue
		}
		item.files = append(item.files, name)
		if info.ModTime().After(item.entry.Updated) {
			item.entry.Updated = info.ModTime()
		}
		if suffix == ".data" {
			dataInfo = info
			item.entry.Size = info.Size()
		} else {
			recordInfo = info
		}
	}
	if recordInfo == nil {
		return item
	}
	item.entry.Kind = "invalid"
	if !recordInfo.Mode().IsRegular() {
		item.entry.Problem = "cache metadata is not a regular file"
		return item
	}
	record, err := readCacheRecord(root, key)
	if err != nil {
		item.entry.Problem = "invalid cache metadata: " + err.Error()
		return item
	}
	if dataInfo == nil || !dataInfo.Mode().IsRegular() {
		item.entry.Problem = "cached data is missing or not a regular file"
		return item
	}
	if record.Size != dataInfo.Size() {
		item.entry.Problem = "cached data size does not match metadata"
		return item
	}
	item.entry = record
	return item
}

func readCacheRecord(root *os.Root, key string) (CacheEntry, error) {
	file, err := root.Open(key + ".json")
	if err != nil {
		return CacheEntry{}, err
	}
	defer file.Close() //nolint:errcheck // read-only
	const maxRecordSize = 64 << 10
	data, err := io.ReadAll(io.LimitReader(file, maxRecordSize+1))
	if err != nil {
		return CacheEntry{}, err
	}
	if len(data) > maxRecordSize {
		return CacheEntry{}, fmt.Errorf("record exceeds %d bytes", maxRecordSize)
	}
	var record CacheEntry
	if err := json.Unmarshal(data, &record); err != nil {
		return CacheEntry{}, err
	}
	if record.Key != key || cacheID(record.Kind, record.URL, record.SHA256) != key ||
		(record.Kind != "artifact" && record.Kind != "metadata") || record.Updated.IsZero() || record.Size < 0 {
		return CacheEntry{}, fmt.Errorf("record fields do not match cache entry")
	}
	record.Problem = ""
	return record, nil
}

// ListCache includes damaged records and orphaned files with a diagnostic in
// Problem. It is read-only and does not let one damaged entry hide healthy ones.
func ListCache(directory string) ([]CacheEntry, error) {
	root, err := os.OpenRoot(directory)
	if errors.Is(err, os.ErrNotExist) {
		return []CacheEntry{}, nil
	}
	if err != nil {
		return nil, err
	}
	defer root.Close() //nolint:errcheck // read-only
	groups, err := scanCacheGroups(root)
	if err != nil {
		return nil, err
	}
	result := []CacheEntry{}
	for _, group := range groups {
		for _, item := range inspectCacheGroup(root, group) {
			result = append(result, item.entry)
		}
	}
	return result, nil
}

// PruneCache removes entries older than cutoff; zero clears the current
// snapshot, including malformed entries and owned orphan/temporary files.
// The global lock protects only discovery. Entry locks protect reinspection and
// deletion, so no unrelated request waits behind another entry's download.
func PruneCache(ctx context.Context, directory string, cutoff time.Time) (int, error) {
	lock, err := lockCache(ctx, directory)
	if err != nil {
		return 0, err
	}
	root, err := os.OpenRoot(directory)
	if err != nil {
		_ = lock.Close()
		if errors.Is(err, os.ErrNotExist) {
			return 0, nil
		}
		return 0, err
	}
	defer root.Close() //nolint:errcheck
	groups, err := scanCacheGroups(root)
	closeErr := lock.Close()
	if err = errors.Join(err, closeErr); err != nil {
		return 0, err
	}
	removed := 0
	for _, group := range groups {
		count, err := pruneCacheGroup(ctx, directory, root, group, cutoff)
		removed += count
		if err != nil {
			return removed, err
		}
	}
	return removed, nil
}

func pruneCacheGroup(ctx context.Context, directory string, root *os.Root, group cacheGroup, cutoff time.Time) (int, error) {
	if group.key != "" {
		lock, err := lockCacheEntry(ctx, directory, group.key)
		if err != nil {
			return 0, err
		}
		defer lock.Close() //nolint:errcheck
	}
	removed := 0
	for _, item := range inspectCacheGroup(root, group) {
		if !cutoff.IsZero() && !item.entry.Updated.Before(cutoff) {
			continue
		}
		for _, name := range item.files {
			if err := ctx.Err(); err != nil {
				return removed, err
			}
			// Only unlink directly owned entries. Never follow JSON paths or
			// recurse into a directory that happens to have a cache filename.
			info, err := root.Lstat(name)
			if errors.Is(err, os.ErrNotExist) || (err == nil && info.IsDir()) {
				continue
			}
			if err != nil {
				return removed, err
			}
			if err := fsops.Retry(func() error { return root.Remove(name) }); err != nil && !errors.Is(err, os.ErrNotExist) {
				return removed, err
			}
		}
		removed++
	}
	return removed, nil
}
